    <rect id="hit" x="${CX - W - 12}" y="${cyOf(0) - H}" width="${2 * W + 24}" height="${cyOf(N - 1) - cyOf(0) + 2 * H + T}" fill="transparent" pointer-events="all" style="cursor:pointer"/>
