const stage = $('#stage');
const plates = [], labs = [];
$$('.plate', stage).forEach((g) => { plates[+g.dataset.i] = g; });
$$('.lab', stage).forEach((d) => { labs[+d.dataset.i] = d; });
const card = $('#card'), cin = $('.cin', card), leader = $('#leader'), ldot = $('#ldot');
const beams = []; $$('.beam', stage).forEach((l) => { beams[+l.dataset.s] = l; });
const rails = $$('#rails line', stage), agents = $$('.agent', stage), pkts = $$('.pkt', stage);
const tplane = $('#tplane', stage), tpPoly = $('.tp', tplane), tpTag = $('.ttag', tplane);
const parts = plates.map((g) => ({
  top: $('.top', g), lf: $('.lf', g), rf: $('.rf', g), iso: $('.iso', g), scanG: $('.scanG', g), scan: $('.scan', g),
  ring: $('.ring', g), rip: $('.rip', g), cyls: $$('.cylPos', g), kpos: $('.kpos', g), pat: $('.pat', g),
}));
const kring = $('.kring', stage);
const wbeams = $$('.wbeam', stage);
